package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.base.Predicate;
import com.google.common.base.Predicates;
import com.google.common.collect.ImmutableSet;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.javascript.jscomp.NodeTraversal.ScopedCallback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Stack;
import java.util.function.Predicate;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.ReferenceCollectingCallback.Reference;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ReferenceCollectingCallback_visit_TriageGen2Test {

    private ReferenceCollectingCallback callback;
    private Predicate<Var> varFilter;
    private Stack<Node> blockStack;

    @Mock private NodeTraversal t;
    @Mock private Scope scope;
    @Mock private Var varInstance;
    @Mock private Node n;
    @Mock private Node parent;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        varFilter = mock(Predicate.class);
        blockStack = new Stack<>();

        // We need to spy on the callback to handle the protected/private fields 
        // like blockStack and varFilter if they aren't accessible via constructor.
        // Since the prompt implies they are part of the class state:
        callback = spy(new ReferenceCollectingCallback());

        // Set internal state via reflection or assuming they are package-private for test
        // For the purpose of this unit test, we assume we can inject these dependencies
        try {
            java.lang.reflect.Field filterField = ReferenceCollectingCallback.class.getDeclaredField("varFilter");
            filterField.setAccessible(true);
            filterField.set(callback, varFilter);

            java.lang.reflect.Field stackField = ReferenceCollectingCallback.class.getDeclaredField("blockStack");
            stackField.setAccessible(true);
            stackField.set(callback, blockStack);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        when(t.getScope()).thenReturn(scope);
    }

    @Test
    public void testVisit_NameMatch_VarExists_FilterTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        when(n.getString()).thenReturn("myVar");
        when(scope.getVar("myVar")).thenReturn(varInstance);
        when(varFilter.apply(varInstance)).thenReturn(true);
        blockStack.push(mock(Node.class));

        callback.visit(t, n, parent);

        verify(callback).addReference(eq(t), eq(varInstance), any(Reference.class));
    }

    @Test
    public void testVisit_NameMatch_VarExists_FilterFalse() {
        when(n.getType()).thenReturn(Token.NAME);
        when(n.getString()).thenReturn("myVar");
        when(scope.getVar("myVar")).thenReturn(varInstance);
        when(varFilter.apply(varInstance)).thenReturn(false);

        callback.visit(t, n, parent);

        verify(callback, never()).addReference(any(), any(), any());
    }

    @Test
    public void testVisit_NameMatch_VarDoesNotExist() {
        when(n.getType()).thenReturn(Token.NAME);
        when(n.getString()).thenReturn("unknown");
        when(scope.getVar("unknown")).thenReturn(null);

        callback.visit(t, n, parent);

        verify(callback, never()).addReference(any(), any(), any());
    }

    @Test
    public void testVisit_NotAName_NoReferenceAdded() {
        when(n.getType()).thenReturn(Token.STRING);

        callback.visit(t, n, parent);

        verify(callback, never()).addReference(any(), any(), any());
    }

    @Test
    public void testVisit_IsBlockBoundary_PopsStack() {
        // Mock isBlockBoundary behavior via spy
        doAnswer(invocation -> true).when(callback).isBlockBoundary(n, parent);
        blockStack.push(mock(Node.class));
        blockStack.push(mock(Node.class));

        callback.visit(t, n, parent);

        assertEquals(1, blockStack.size());
    }

    @Test
    public void testVisit_NotBlockBoundary_NoPop() {
        doAnswer(invocation -> false).when(callback).isBlockBoundary(n, parent);
        blockStack.push(mock(Node.class));

        callback.visit(t, n, parent);

        assertEquals(1, blockStack.size());
    }

    @Test
    public void testVisit_NameAndBlockBoundary() {
        // Test both branches in one go
        when(n.getType()).thenReturn(Token.NAME);
        when(n.getString()).thenReturn("v");
        when(scope.getVar("v")).thenReturn(varInstance);
        when(varFilter.apply(varInstance)).thenReturn(true);
        doAnswer(invocation -> true).when(callback).isBlockBoundary(n, parent);

        blockStack.push(mock(Node.class));
        blockStack.push(mock(Node.class));

        callback.visit(t, n, parent);

        verify(callback).addReference(eq(t), eq(varInstance), any(Reference.class));
        assertEquals(1, blockStack.size());
    }

    // Helper to allow verify on the spy
    private <T> T eq(T value) {
        return org.mockito.ArgumentMatchers.eq(value);
    }
}
